<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/vendor/autoload.php';
$_SESSION['cart']=$_SESSION['cart']??[];$_SESSION['checkout_key']=$_SESSION['checkout_key']??bin2hex(random_bytes(32));
$error='';$success=null;$items=[];$total=0;$deliveryFee=0.0;$displayDeliveryFee=0.0;try{$feeQ=db()->prepare("SELECT setting_value FROM settings WHERE setting_key='delivery_fee'");$feeQ->execute();$deliveryFee=max(0,(float)($feeQ->fetchColumn()?:0));$displayDeliveryFee=(($_POST['fulfillment_method']??'delivery')==='delivery')?$deliveryFee:0.0;}catch(Throwable){}
if($_SESSION['cart']){
 try{$ids=array_map('intval',array_keys($_SESSION['cart']));$marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT p.id,p.name,p.sku,p.price,p.stock_quantity,p.reserved_quantity FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id IN ($marks) AND p.status='active' AND p.compliance_status='approved' AND c.is_active=1 AND c.compliance_status='approved'");$q->execute($ids);$items=$q->fetchAll();foreach($items as $it){$qty=(int)$_SESSION['cart'][$it['id']];$total+=(float)$it['price']*$qty;}}catch(Throwable $e){error_log($e->getMessage());$error='تعذر تحميل محتويات السلة.';}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$error){
 if(!hash_equals($_SESSION['_csrf']??'',(string)($_POST['_csrf']??''))){http_response_code(419);exit('انتهت صلاحية الطلب.');}
 $name=trim((string)($_POST['full_name']??''));$phone=preg_replace('/[^0-9+]/','',(string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$method=(string)($_POST['fulfillment_method']??'delivery');$city=trim((string)($_POST['city']??''));$address=trim((string)($_POST['address']??''));$note=trim((string)($_POST['customer_note']??''));
 if(!$items||mb_strlen($name)<3||mb_strlen($name)>160||strlen($phone)<8||strlen($phone)>20||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||!in_array($method,['delivery','pickup'],true)||($method==='delivery'&&(mb_strlen($city)<2||mb_strlen($address)<5))){$error='يرجى إدخال بيانات صحيحة وإكمال حقول التوصيل المطلوبة.';}
 else{
  $pdo=db();
  try{$pdo->beginTransaction();$locked=[];$sum=0;
   foreach($_SESSION['cart'] as $pid=>$qty){$q=$pdo->prepare("SELECT p.id,p.name,p.sku,p.price,p.stock_quantity,p.reserved_quantity,p.status,p.compliance_status,c.is_active,c.compliance_status category_compliance FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? FOR UPDATE");$q->execute([(int)$pid]);$p=$q->fetch();$qty=(int)$qty;if(!$p||$p['status']!=='active'||$p['compliance_status']!=='approved'||!(int)$p['is_active']||$p['category_compliance']!=='approved'||$qty<1||$qty>((int)$p['stock_quantity']-(int)$p['reserved_quantity']))throw new RuntimeException('تغير توفر أحد المنتجات. راجع السلة ثم حاول مجدداً.');$p['quantity']=$qty;$p['line_total']=(float)$p['price']*$qty;$sum+=$p['line_total'];$locked[]=$p;}
   $q=$pdo->prepare("INSERT INTO customers(full_name,phone,email) VALUES(?,?,?)");$q->execute([$name,$phone,$email?:null]);$customerId=(int)$pdo->lastInsertId();
   $orderNumber='AF-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$orderDeliveryFee=$method==='delivery'?$deliveryFee:0.0;$grand=$sum+$orderDeliveryFee;$key=$_SESSION['checkout_key'];
   $q=$pdo->prepare("INSERT INTO orders(order_number,customer_id,fulfillment_method,city,address,customer_note,status,subtotal,delivery_fee,total,idempotency_key) VALUES(?,?,?,?,?,?,'new',?,?,?,?)");
   $q->execute([$orderNumber,$customerId,$method,$method==='delivery'?$city:null,$method==='delivery'?$address:null,$note?:null,$sum,$orderDeliveryFee,$grand,$key]);$orderId=(int)$pdo->lastInsertId();
   $line=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name_snapshot,sku_snapshot,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)");
   foreach($locked as $p)$line->execute([$orderId,$p['id'],$p['name'],$p['sku'], $p['price'],$p['quantity'],$p['line_total']]);
   $pdo->prepare("INSERT INTO order_status_history(order_id,old_status,new_status,note) VALUES(?,NULL,'new','تم إنشاء الطلب بانتظار مراجعة الإدارة')")->execute([$orderId]);
   $pdo->commit();$_SESSION['cart']=[];unset($_SESSION['checkout_key']);$success=$orderNumber;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'تعذر إنشاء الطلب حالياً. حاول مرة أخرى.';}
 }
}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إتمام الطلب | الفخامة</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css"><style>.checkout{display:grid;grid-template-columns:1.2fr .8fr;gap:24px}.checkout-panel{padding:22px;border:1px solid #49371c;border-radius:16px;background:#111}.checkout label{display:block;margin:12px 0 5px}.checkout input,.checkout textarea,.checkout select{width:100%;padding:12px;border-radius:9px;border:1px solid #49371c;background:#080808;color:white;font:inherit}.checkout textarea{min-height:90px}.summary-line{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #302719}.summary-total{font-size:22px;color:#f4c45e;padding-top:18px}@media(max-width:720px){.checkout{grid-template-columns:1fr}}</style></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="./"><span class="brand-mark">ف</span><span><strong>الفخامة</strong><small>AL FAKHAMAH</small></span></a><a class="btn btn-outline" href="cart.php">العودة للسلة</a></div></header><main class="section"><div class="container"><span class="eyebrow">خطوة أخيرة</span><h1>إتمام الطلب</h1><?php if($success):?><div class="empty-state"><span>✓</span><h2>تم استلام طلبك بنجاح</h2><p>رقم الطلب: <strong><?=e($success)?></strong></p><p>طلبك جديد وبانتظار مراجعة الإدارة.</p><a class="btn btn-gold" href="./">العودة للمتجر</a></div><?php elseif(!$items):?><div class="empty-state"><h3>سلتك فارغة</h3><a class="btn btn-gold" href="./">تصفح المنتجات</a></div><?php else:?><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><div class="checkout"><form class="checkout-panel" method="post"><input type="hidden" name="_csrf" value="<?=e(App\Security::csrfToken())?>"><h2>بيانات العميل</h2><label>الاسم الكامل</label><input name="full_name" required minlength="3" maxlength="160" value="<?=e((string)($_POST['full_name']??''))?>"><label>رقم الهاتف</label><input name="phone" type="tel" required maxlength="20" value="<?=e((string)($_POST['phone']??''))?>"><label>البريد الإلكتروني (اختياري)</label><input name="email" type="email" value="<?=e((string)($_POST['email']??''))?>"><label>طريقة الاستلام</label><select id="fulfillment_method" name="fulfillment_method"><option value="delivery" <?=($_POST['fulfillment_method']??'delivery')==='delivery'?'selected':''?>>التوصيل إلى العنوان</option><option value="pickup" <?=($_POST['fulfillment_method']??'delivery')==='pickup'?'selected':''?>>الاستلام من المحل</option></select><label>المدينة (للتوصيل)</label><input name="city" maxlength="120" value="<?=e((string)($_POST['city']??''))?>"><label>العنوان بالتفصيل (للتوصيل)</label><textarea name="address"><?=e((string)($_POST['address']??''))?></textarea><label>ملاحظات إضافية</label><textarea name="customer_note"><?=e((string)($_POST['customer_note']??''))?></textarea><button class="btn btn-gold" type="submit">تأكيد وإرسال الطلب</button></form><aside class="checkout-panel"><h2>ملخص الطلب</h2><?php foreach($items as $it):?><div class="summary-line"><span><?=e($it['name'])?> × <?= (int)$_SESSION['cart'][$it['id']]?></span><b><?=number_format((float)$it['price']*(int)$_SESSION['cart'][$it['id']],2)?> ر.س</b></div><?php endforeach;?><div class="summary-line"><span>المجموع</span><b><?=number_format($total,2)?> ر.س</b></div><div class="summary-line"><span>رسوم التوصيل</span><b id="delivery-fee-value"><?=number_format($displayDeliveryFee,2)?> ر.س</b></div><div class="summary-total">الإجمالي المبدئي: <span id="checkout-grand-total"><?=number_format($total+$displayDeliveryFee,2)?></span> ر.س</div><small style="color:#aaa">لا يتم تحصيل أي مبلغ إلكترونياً في هذه المرحلة. الطلب بانتظار مراجعة الإدارة.</small></aside></div><?php endif;?></div></main><script>(()=>{const method=document.getElementById("fulfillment_method");const fee=Number(<?=json_encode($deliveryFee)?>);const subtotal=Number(<?=json_encode($total)?>);const feeNode=document.getElementById("delivery-fee-value");const totalNode=document.getElementById("checkout-grand-total");const city=document.querySelector("[name=city]");const address=document.querySelector("[name=address]");function update(){const delivery=method.value==="delivery";const amount=delivery?fee:0;if(feeNode)feeNode.textContent=amount.toFixed(2)+" ر.س";if(totalNode)totalNode.textContent=(subtotal+amount).toFixed(2);if(city)city.required=delivery;if(address)address.required=delivery;}method.addEventListener("change",update);update();})();</script></body></html>